@section('content')<form method="post" action="/orders">@csrf<div class="grid"><div><div class="card"><h2>Customer & pricing</h2><div class="fields section-gap"><div><label>Customer · search name / phone / tax ID</label><select name="customer_id" id="customer" required data-searchable data-search-label="ค้นหาลูกค้าด้วยชื่อ เบอร์โทร หรือเลขผู้เสียภาษี"></select></div><div><label>Price category</label><select name="channel" id="channel">@foreach(['retail'=>'Retail','hospital'=>'Hospital','pharmacy'=>'Pharmacy'] as $key=>$label)<option value="{{ $key }}" @selected(old('channel')===$key)>{{ $label }}</option>@endforeach</select></div><div><label>Customer tax ID (13 digits)</label><input id="tax_id" name="tax_id" maxlength="13" pattern="[0-9]{13}" value="{{ old('tax_id') }}"></div><div><label>Order date</label><input type="date" name="order_date" value="{{ old('order_date',now()->toDateString()) }}" required></div><div><label>Salesperson</label><input name="salesperson" value="{{ old('salesperson','Demo Sales Team') }}" required></div><div><label>Salesperson code</label><input name="sales_code" value="{{ old('sales_code') }}"></div><div><label>Salesperson phone</label><input name="sales_phone" value="{{ old('sales_phone') }}"></div></div></div><div class="card section-gap"><div class="card-top"><h2>Order items</h2><button type="button" id="add-line">＋ Add item</button></div><div id="lines"></div></div></div><div class="card" style="align-self:start"><h2>Order summary</h2><div class="total-box section-gap"><div><span>Quantity sold</span><b id="units">0</b></div><div><span>Free units by SKU</span><b id="free">0</b></div><div><span>Discount</span><b id="discount">0</b></div><div><span>Excluding VAT</span><b id="net">0</b></div><div><span>VAT 7%</span><b id="vat">0</b></div><div class="grand"><span>Total</span><b id="total">0</b></div></div><p id="pricing-error" class="section-gap"></p><button class="section-gap" id="confirm">Confirm order</button><p class="section-gap">ของแ