@section('scripts')<script>
const products=@json($products), customers=@json($customers), previous=@json(array_values(old('lines',[]))), oldCustomer=@json(old('customer_id')),oldChannel=@json(old('channel')),oldTax=@json(old('tax_id'));const customer=document.querySelector('#customer'),channel=document.querySelector('#channel'),lines=document.querySelector('#lines');let counter=0;const money=x=>'฿'+(x/100).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
function listCustomers(term=''){const selected=customer.value||String(oldCustomer||customers[0]?.id||'');customer.replaceChildren();customers.filter(c=>(c.name+' '+c.phone+' '+(c.tax_id||'')).toLowerCase().includes(term.toLowerCase())).forEach(c=>{const o=document.createElement('option');o.value=c.id;o.textContent=c.name+' · '+c.phone;o.dataset.search=c.tax_id||'';customer.append(o)});if([...customer.options].some(o=>o.value===selected))customer.value=selected;else selectCustomer();if(!customer.options.length)document.querySelector('#tax_id').value='';calculate()}
function selectCustomer(){const c=customers.find(c=>c.id==customer.value);if(c){channel.value=c.channel;document.querySelector('#tax_id').value=c.tax_id||'';resetPrices()}}
function resetPrices(){for(const row of lines.children){const p=products.find(p=>p.id==row.querySelector('select').value);row.querySelector('.negotiated').value=p[channel.value]===null?'':(p[channel.value]/100).toFixed(2);row.querySelector('.reason').value=''}calculate()}
function field(row,label,key,value,type='number'){const wrap=document.createElement('div'),caption=document.createElement('label'),input=document.createElement('input');caption.textContent=label;input.type=type;input.name=`lines[${row.dataset.index}][${key}]`;input.value=value??'';if(type==='number'){input.min=0;input.max=key==='discount_percent'?100:(key==='price'?1000000:10000);input.step=['price','discount_percent'].includes(key)?'0.01':'1';input.required=true;}if(key==='price')input.className='negotiated';if(key==='price_reason')input.className='reason';wrap.append(caption,input);row.append(wrap);return input}
function addLine(saved={}){const row=document.createElement('div');row.className='item-card';row.dataset.index=counter++;const label=document.createElement('label');label.textContent='Product';const select=document.createElement('select');select.dataset.searchable='';select.dataset.searchLabel='ค้นหาสินค้าด้วยชื่อหรือ SKU';select.name=`lines[${row.dataset.index}][product_id]`;products.forEach(p=>{const o=document.createElement('option');o.value=p.id;o.textContent=p.sku+' · '+p.name+' ('+p.unit+') · available '+(p.stock_on_hand-p.stock_reserved);select.append(o)});if(saved.product_id)select.value=saved.product_id;row.append(label,select);field(row,'Quantity sold','quantity',saved.quantity??1);field(row,'Free quantity (same SKU)','free_quantity',saved.free_quantity??0);const p=products.find(p=>p.id==select.value);field(row,'Selling price / unit (THB)','price',saved.price??(p[channel.value]===null?'':p[channel.value]/100));field(row,'Discount (%)','discount_percent',saved.discount_percent??0);field(row,'Price adjustment reason','price_reason',saved.price_reason??'','text');const hint=document.createElement('small');hint.className='catalog muted';row.append(hint);const remove=document.createElement('button');remove.type='button';remove.className='remove';remove.textContent='Remove item';remove.onclick=()=>{row.remove();calculate()};row.append(remove);select.onchange=()=>{const p=products.find(p=>p.id==select.value);row.querySelector('.negotiated').value=p[channel.value]===null?'':p[channel.value]/100;row.querySelector('.reason').value='';calculate()};row.oninput=calculate;lines.append(row);calculate()}
function calculate(){let total=0,discount=0,units=0,box=0,sachet=0,invalid=!customer.value||!lines.children.length;for(const row of lines.children){const p=products.find(p=>p.id==row.querySelector('select').value),base=p[channel.value],q=+row.querySelector('[name$="[quantity]"]').value,price=row.querySelector('.negotiated'),reason=row.querySelector('.reason');row.querySelector('.catalog').textContent='Catalog price: '+(base===null?'Not set':money(base))+' · Unit: '+p.unit+' · Available: '+(p.stock_on_hand-p.stock_reserved);price.required=q>0;reason.required=q>0&&price.value!==''&&Math.round(+price.value*100)!==base;invalid ||= q>0&&price.value==='';units+=q;box+=+row.querySelector('[name$="[free_quantity]"]').value;const gross=Math.round(+price.value*100)*q,bp=Math.round(+row.querySelector('[name$="[discount_percent]"]').value*100),deduction=Math.floor((gross*bp+5000)/10000);discount+=deduction;total+=gross-deduction;}const net=Math.round(total/1.07);for(const [id,value] of Object.entries({total:money(total),discount:money(discount),net:money(net),vat:money(total-net),units,free:box}))document.getElementById(id).textContent=value;document.getElementById('confirm').disabled=invalid;document.getElementById('pricing-error').textContent=invalid?'Select a customer and enter a price for each item.':''}
customer.onchange=selectCustomer;channel.onchange=resetPrices;document.querySelector('#add-line').onclick=()=>addLine();listCustomers();selectCustomer();if(oldChannel)channel.value=oldChannel;if(oldTax!==null)document.querySelector('#tax_id').value=oldTax;if(previous.length)previous.forEach(addLine);else addLine();
</script>@endsection
